package containers

import (
	"context"
	"errors"
	"fmt"
	"net/netip"
	"sort"
	"time"
)

type RecipeVerifier interface{Verify(context.Context,ApplicationRecipe)error}
type IDAllocator interface{For(context.Context,ID,string,string)(ID,error)}
type ApplicationService struct{containers *Service;repository Repository;verifier RecipeVerifier;allocator IDAllocator;clock func()time.Time}
func NewApplicationService(containers *Service,repository Repository,verifier RecipeVerifier,allocator IDAllocator)(*ApplicationService,error){if containers==nil||nilValue(repository)||nilValue(verifier)||nilValue(allocator){return nil,ErrInvalid};return &ApplicationService{containers:containers,repository:repository,verifier:verifier,allocator:allocator,clock:time.Now},nil}
func(a *ApplicationService)RegisterRecipe(ctx context.Context,recipe ApplicationRecipe)error{if !recipe.ID.Valid()||recipe.Version==""||recipe.SigningKeyID==""||recipe.Signature==""||len(recipe.Digest)!=64||len(recipe.SignatureDigest)!=64||len(recipe.Workloads)==0{return ErrInvalid};if err:=a.verifier.Verify(ctx,recipe);err!=nil{return err};names:=map[string]bool{};for _,workload:=range recipe.Workloads{if names[workload.Name]{return ErrConflict};names[workload.Name]=true;if err:=workload.Spec.Validate(TierTenantRootless);err!=nil{return err}};return a.repository.PutRecipe(ctx,recipe)}

type DeployApplicationCommand struct{Meta CommandMeta;ApplicationID,SiteID,RecipeID ID;RecipeVersion string}
func(a *ApplicationService)Deploy(ctx context.Context,command DeployApplicationCommand)(ContainerApplication,[]Result,error){now:=a.clock().UTC();if err:=command.Meta.Validate("application.deploy",command.ApplicationID,now);err!=nil{return ContainerApplication{},nil,err};recipe,err:=a.repository.Recipe(ctx,command.RecipeID,command.RecipeVersion);if err!=nil{return ContainerApplication{},nil,err};if err=a.verifier.Verify(ctx,recipe);err!=nil{return ContainerApplication{},nil,err};application:=ContainerApplication{ID:command.ApplicationID,TenantID:command.Meta.Grant.TenantID,SiteID:command.SiteID,RecipeID:recipe.ID,RecipeVersion:recipe.Version,State:"deploying",ActiveGeneration:1,CandidateGeneration:1,CreatedAt:now,UpdatedAt:now};results:=make([]Result,0);for _,volumeSpec:=range recipe.Volumes{id,allocErr:=a.allocator.For(ctx,application.ID,"volume",volumeSpec.Name);if allocErr!=nil{return application,results,allocErr};meta:=deriveMeta(command.Meta,"volume.ensure",id,volumeSpec.Name);volume,result,ensureErr:=a.containers.EnsureVolume(ctx,EnsureVolumeCommand{Meta:meta,VolumeID:id,Name:volumeSpec.Name,Class:volumeSpec.Class,QuotaBytes:volumeSpec.QuotaBytes,InodeLimit:volumeSpec.InodeLimit});if ensureErr!=nil{return application,results,ensureErr};application.VolumeIDs=append(application.VolumeIDs,volume.ID);results=append(results,result)};for _,networkSpec:=range recipe.Networks{id,allocErr:=a.allocator.For(ctx,application.ID,"network",networkSpec.Name);if allocErr!=nil{return application,results,allocErr};prefix:=netip.MustParsePrefix("10.0.0.0/24");meta:=deriveMeta(command.Meta,"network.ensure",id,networkSpec.Name);network,result,ensureErr:=a.containers.EnsureNetwork(ctx,EnsureNetworkCommand{Meta:meta,NetworkID:id,Name:networkSpec.Name,IPv4:prefix,Internal:networkSpec.Internal,DNSPolicy:"tenant"});if ensureErr!=nil{return application,results,ensureErr};application.NetworkIDs=append(application.NetworkIDs,network.ID);results=append(results,result)};ordered,err:=sortRecipeWorkloads(recipe.Workloads);if err!=nil{return application,results,err};for _,workloadSpec:=range ordered{id,allocErr:=a.allocator.For(ctx,application.ID,"workload",workloadSpec.Name);if allocErr!=nil{return application,results,allocErr};spec:=workloadSpec.Spec;for index,mount:=range spec.Volumes{for recipeIndex,recipeVolume:=range recipe.Volumes{if mount.VolumeID.String()==recipeVolume.Name||mount.VolumeID.String()=="vol_"+recipeVolume.Name{spec.Volumes[index].VolumeID=application.VolumeIDs[recipeIndex]}}};for index,attachment:=range spec.Networks{for recipeIndex,recipeNetwork:=range recipe.Networks{if attachment.NetworkID.String()==recipeNetwork.Name||attachment.NetworkID.String()=="net_"+recipeNetwork.Name{spec.Networks[index].NetworkID=application.NetworkIDs[recipeIndex]}}};meta:=deriveMeta(command.Meta,"workload.apply",id,workloadSpec.Name);workload,result,applyErr:=a.containers.ApplyWorkload(ctx,ApplyWorkloadCommand{Meta:meta,WorkloadID:id,SiteID:application.SiteID,Name:workloadSpec.Name,Tier:TierTenantRootless,Spec:spec});if applyErr!=nil{return application,results,applyErr};application.WorkloadIDs=append(application.WorkloadIDs,workload.ID);results=append(results,result)};application.State="active";application.CandidateGeneration=0;operation:=Operation{EffectID:EffectID("app-"+digestValue(command)),TenantID:application.TenantID,ResourceID:application.ID,CommandDigest:digestValue(command),Status:"accepted",CreatedAt:now};_,err=a.repository.Admit(ctx,operation,application,0);if err!=nil{return application,results,err};if err=a.repository.Complete(ctx,operation.EffectID,"applied",application,map[string]any{"results":results});err!=nil{return application,results,err};return application,results,nil}

type UpdateApplicationCommand struct{Meta CommandMeta;ApplicationID ID;RecipeID ID;RecipeVersion string;BackwardCompatibleData bool}
func(a *ApplicationService)Update(ctx context.Context,command UpdateApplicationCommand)(ContainerApplication,[]Result,error){application,err:=a.repository.Application(ctx,command.Meta.Grant.TenantID,command.ApplicationID);if err!=nil{return ContainerApplication{},nil,err};if application.ActiveGeneration!=command.Meta.ExpectedGeneration{return application,nil,ErrStale};snapshot,err:=a.containers.backups.SnapshotVolumes(ctx,application.ID,application.VolumeIDs);if err!=nil{return application,nil,err};previous:=application;application.State="updating";application.CandidateGeneration=application.ActiveGeneration+1;deploy:=DeployApplicationCommand{Meta:command.Meta,ApplicationID:application.ID,SiteID:application.SiteID,RecipeID:command.RecipeID,RecipeVersion:command.RecipeVersion};deploy.Meta.ExpectedGeneration=application.ActiveGeneration;candidate,results,err:=a.Deploy(ctx,deploy);if err!=nil{_ = a.containers.backups.RestoreVolumes(ctx,snapshot,previous.VolumeIDs);return previous,results,err};candidate.ActiveGeneration=application.CandidateGeneration;candidate.CandidateGeneration=0;candidate.DataGeneration=previous.DataGeneration;if !command.BackwardCompatibleData{written:=a.clock().UTC();candidate.FirstWriteAt=&written};candidate.UpdatedAt=a.clock().UTC();return candidate,results,nil}

func(a *ApplicationService)Rollback(ctx context.Context,tenant,applicationID ID,snapshot string,previous ContainerApplication)(ContainerApplication,error){current,err:=a.repository.Application(ctx,tenant,applicationID);if err!=nil{return ContainerApplication{},err};if current.FirstWriteAt!=nil||current.DataGeneration!=previous.DataGeneration{return current,fmt.Errorf("%w: application crossed write frontier",ErrConflict)};if err=a.containers.backups.RestoreVolumes(ctx,snapshot,previous.VolumeIDs);err!=nil{return current,err};previous.UpdatedAt=a.clock().UTC();return previous,nil}

func deriveMeta(parent CommandMeta,operation string,resource ID,variant string)CommandMeta{parent.CommandID=parent.CommandID+"."+variant;parent.Grant.Operation=operation;parent.Grant.ResourceID=resource;parent.Grant.Digest=digestValue(struct{Parent,Operation,Resource string}{parent.CommandID,operation,resource.String()});parent.ExpectedGeneration=0;parent.Fence++;return parent}
func sortRecipeWorkloads(values []RecipeWorkload)([]RecipeWorkload,error){remaining:=make(map[string]RecipeWorkload,len(values));for _,value:=range values{remaining[value.Name]=value};result:=make([]RecipeWorkload,0,len(values));for len(remaining)>0{names:=make([]string,0,len(remaining));for name:=range remaining{names=append(names,name)};sort.Strings(names);progress:=false;for _,name:=range names{value:=remaining[name];ready:=true;for _,dependency:=range value.DependsOn{if _,pending:=remaining[dependency];pending{ready=false;break}};if ready{result=append(result,value);delete(remaining,name);progress=true}};if !progress{return nil,errors.New("container recipe dependency cycle")}};return result,nil}
